/* ------------------------------------------------------------------------------------------------------------------
 * the raw records (re-read from f->path: mcam_load keeps only decoded fields). Framing = viewer/mcam_load.c mcam_load
 * (u32 size + record until size 0 / past EOF = the binary NCI; the op_group table after a sub 0xF header record, the
 * material table after sub 0xE, a Parasolid body after a 0x20000 record).
 * ------------------------------------------------------------------------------------------------------------------ */
typedef struct { const uint8_t *p; uint32_t n; } Rec;
static struct {
    char path[1024]; long long size, mtime; int ok;
    uint8_t *buf;
    Rec mach, ctl, pg[12], grp;
    Rec *md; int *mdsub, nmd, cmd;      /* machine definition records: ASSOC sub 12 / 13 / 15 / 21 / 26 (see md_* below) */
    int mdok;                           /* md_build() done for this load */
} C;

static uint32_t rd32(const uint8_t *p) { return p[0] | p[1] << 8 | p[2] << 16 | (uint32_t)p[3] << 24; }
static uint16_t rd16(const uint8_t *p) { return (uint16_t)(p[0] | p[1] << 8); }

static void load(const McamFile *f) {
    if (C.ok && !strcmp(C.path, f->path) && C.size == f->file_size && C.mtime == f->file_mtime) return;
    free(C.buf); free(C.md); free(C.mdsub); memset(&C, 0, sizeof C);
    snprintf(C.path, sizeof C.path, "%s", f->path); C.size = f->file_size; C.mtime = f->file_mtime; C.ok = 1;
    FILE *fp = fopen(f->path, "rb"); if (!fp) return;
    fseek(fp, 0, SEEK_END); long len = ftell(fp); fseek(fp, 0, SEEK_SET);
    if (len < 0x9c || !(C.buf = malloc((size_t)len))) { fclose(fp); return; }
    if (fread(C.buf, 1, (size_t)len, fp) != (size_t)len) { fclose(fp); free(C.buf); C.buf = NULL; return; }
    fclose(fp);
    const uint8_t *d = C.buf; size_t off = 0, L = (size_t)len;
    enum { MAXR = 256 }; Rec m22[MAXR], c23[MAXR], p24[MAXR * 4]; int n22 = 0, n23 = 0, n24 = 0; int i24at23[MAXR];
    const uint8_t *grp = NULL;
    while (off + 4 <= L) {
        uint32_t n = rd32(d + off);
        if (n == 0 || off + 4 + n > L) break;
        const uint8_t *rec = d + off + 4; off += 4 + n;
        if (n >= 0x70 && rd32(rec) == 0x4000) {
            int sub = (int32_t)rd32(rec + 0x2c);
            if (sub == 22 && n == 5000 && n22 < MAXR) m22[n22++] = (Rec){ rec, n };
            else if (sub == 23 && n23 < MAXR) { i24at23[n23] = n24; c23[n23++] = (Rec){ rec, n }; }
            else if (sub == 24 && n >= 0x6c && n24 < MAXR * 4) p24[n24++] = (Rec){ rec, n };
            if (sub == 12 || sub == 13 || sub == 15 || sub == 21 || sub == 26) {   /* the machine definition (md_*) */
                if (C.nmd == C.cmd) {
                    C.cmd = C.cmd ? 2 * C.cmd : 256;
                    C.md = realloc(C.md, (size_t)C.cmd * sizeof *C.md); C.mdsub = realloc(C.mdsub, (size_t)C.cmd * sizeof *C.mdsub);
                }
                C.md[C.nmd] = (Rec){ rec, n }; C.mdsub[C.nmd++] = sub;
            }
        } else if (n >= 0x6a && rd32(rec) == 0x200) {
            uint16_t sub = rd16(rec + 0x68);
            if (sub == 0xF && off + 4 <= L) {
                uint32_t ng = rd32(d + off);
                /* the active machine group = the last top-level one (op_group +0x10c parent = 0), mcam_load.c */
                if (ng && off + 4 + 0x1ae0 <= L) {
                    grp = d + off + 4;
                    for (uint32_t k = 1; k < ng && off + 4 + (k + 1) * (size_t)0x1ae0 <= L; k++)
                        if (rd32(d + off + 4 + k * 0x1ae0 + 0x10c) == 0) grp = d + off + 4 + k * 0x1ae0;
                    if (f->grp_rec)          /* the group mcam_load chose (same rule; its id) */
                        for (uint32_t k = 0; k < ng && off + 4 + (k + 1) * (size_t)0x1ae0 <= L; k++)
                            if ((int32_t)rd32(d + off + 4 + k * 0x1ae0) == f->grp_id) { grp = d + off + 4 + k * 0x1ae0; break; }
                }
                off += 4 + (size_t)ng * 0x1ae0;
                if (off > L) break;
            } else if (sub == 0xE) {
                while (off + 0x28 <= L) {
                    int32_t id = (int32_t)rd32(d + off); uint64_t s = rd32(d + off + 0x10) | (uint64_t)rd32(d + off + 0x14) << 32;
                    off += 0x28; if (id == 0) break; if (s > L - off) { off = L; break; } off += s;
                }
            }
        } else if (n >= 0x16c && rd32(rec) == 0x20000) {
            uint8_t ver = rec[0x49]; uint32_t xs = rd32(rec + 0x168);
            if (xs > L - off) break;
            off += xs; off += 4 + (ver > 0x1b ? 0x100 : 0x40); off += 1 + 1 + 4 + 4 + 8;
            if (off + 4 > L) break;
            uint32_t cnt = rd32(d + off); off += 4;
            for (uint32_t i = 0; i < cnt && off + 8 <= L; i++) { size_t sk = 8 + (size_t)rd32(d + off + 4); if (sk > L - off) { off = L; break; } off += sk; }
        }
    }
    if (grp) C.grp = (Rec){ grp, 0x1ae0 };
    /* machine: the record whose ent id (+0x34) = the active group's +0x1170 (f->mach_id from mcam_load resolve_machine),
       else the first one (resolve_machine's fallback) */
    for (int i = 0; i < n22 && !C.mach.p; i++) if (f->mach_id && (int32_t)rd32(m22[i].p + 0x34) == f->mach_id) C.mach = m22[i];
    if (!C.mach.p && n22) C.mach = m22[0];
    int ctl_id = C.mach.p ? (int32_t)rd32(C.mach.p + 0xe94) : 0, ci = -1;
    for (int i = 0; i < n23 && ci < 0; i++) if ((int32_t)rd32(c23[i].p + 0x34) == ctl_id) ci = i;
    if (ci >= 0) {
        C.ctl = c23[ci];
        /* pages: ent id = control id + 1 + page and +0x68 = page; else the page records following the control record
           (resolve_machine; the stored link field is NOT DECODED) */
        for (int i = 0; i < n24; i++) {
            int p = (int32_t)rd32(p24[i].p + 0x68), id = (int32_t)rd32(p24[i].p + 0x34);
            if (p >= 0 && p < 12 && id == ctl_id + 1 + p && !C.pg[p].p) C.pg[p] = p24[i];
        }
        int end = ci + 1 < n23 ? i24at23[ci + 1] : n24;
        for (int i = i24at23[ci]; i < end; i++) {
            int p = (int32_t)rd32(p24[i].p + 0x68);
            if (p >= 0 && p < 12 && !C.pg[p].p) C.pg[p] = p24[i];
        }
    }
}

MpPrmFound mp_prm_found(const McamFile *f) {
    load(f);
    MpPrmFound r = { C.mach.p != NULL, C.ctl.p != NULL, 0, C.grp.p != NULL };
    for (int p = 0; p < 12; p++) if (C.pg[p].p) r.pages |= 1 << p;
    return r;
}

/* ------------------------------------------------------------------------------------------------------------------
 * parameter lists
 * ------------------------------------------------------------------------------------------------------------------ */
typedef struct { int code; double v; } NumP;
typedef struct { int code; char *s; } StrP;
typedef struct { NumP *num; int nn, cn; StrP *str; int ns, cs; int missing; } PList;

static void pl_free(PList *l) { for (int i = 0; i < l->ns; i++) free(l->str[i].s); free(l->num); free(l->str); memset(l, 0, sizeof *l); }
/* std::map insert: a code already present keeps its first value (FUN_18000cb60 / FUN_18000cd00 do not overwrite) */
static void add_num(PList *l, int code, double v) {
    for (int i = 0; i < l->nn; i++) if (l->num[i].code == code) return;
    if (l->nn == l->cn) { l->cn = l->cn ? 2 * l->cn : 256; l->num = realloc(l->num, l->cn * sizeof *l->num); }
    l->num[l->nn++] = (NumP){ code, v };
}
static void add_str(PList *l, int code, const char *s) {
    for (int i = 0; i < l->ns; i++) if (l->str[i].code == code) return;
    if (l->ns == l->cs) { l->cs = l->cs ? 2 * l->cs : 64; l->str = realloc(l->str, l->cs * sizeof *l->str); }
    l->str[l->ns++] = (StrP){ code, strdup(s) };
}
static int cmp_num(const void *a, const void *b) { int x = ((const NumP *)a)->code, y = ((const NumP *)b)->code; return (x > y) - (x < y); }
static int cmp_str(const void *a, const void *b) { int x = ((const StrP *)a)->code, y = ((const StrP *)b)->code; return (x > y) - (x < y); }

static int field(const Rec *r, int off, int ct, double *v) {
    static const int sz[] = { 1, 1, 2, 2, 4, 4, 4, 8, 1 };
    if (!r->p || off < 0 || (uint32_t)(off + sz[ct]) > r->n) return 0;
    const uint8_t *p = r->p + off;
    switch (ct) {
    case T_I8: *v = (int8_t)p[0]; break;
    case T_U8: *v = p[0]; break;
    case T_I16: *v = (int16_t)rd16(p); break;
    case T_U16: *v = rd16(p); break;
    case T_I32: *v = (int32_t)rd32(p); break;
    case T_U32: *v = rd32(p); break;
    case T_F32: { float x; memcpy(&x, p, 4); *v = x; break; }
    case T_F64: memcpy(v, p, 8); break;
    default: return 0;
    }
    return 1;
}
/* CString(const char *) of a char[] field: up to its NUL (bounded by the record) */
static int cstrf(const Rec *r, int off, char *dst, size_t n) {
    if (!r->p || off < 0 || (uint32_t)off >= r->n) return 0;
    size_t i = 0; for (; i + 1 < n && off + i < r->n && r->p[off + i]; i++) dst[i] = (char)r->p[off + i];
    dst[i] = 0; return 1;
}
/* UuidToStringA (rpcrt4) text of a GUID: Data1 / Data2 / Data3 little-endian, Data4 bytes; lower case. MdComponentId::
   ToString @18013f900 upper-cases it (_mbsupr_s), PrmMachine::AddId @18003c120 does not */
static int uuidf(const Rec *r, int off, int upper, char *dst, size_t n) {
    if (!r->p || off < 0 || (uint32_t)(off + 16) > r->n) return 0;
    const uint8_t *g = r->p + off;
    snprintf(dst, n, "%08x-%04x-%04x-%02x%02x-%02x%02x%02x%02x%02x%02x", rd32(g), rd16(g + 4), rd16(g + 6),
             g[8], g[9], g[10], g[11], g[12], g[13], g[14], g[15]);
    if (upper) for (char *c = dst; *c; c++) *c = (char)toupper((unsigned char)*c);
    return 1;
}

static const Rec *src_rec(int src, const Rec *op) {
    switch (src) {
    case S_CTL_BASE: return &C.ctl;
    case S_GRP: return &C.grp;
    case S_MACH: return &C.mach;
    case S_OP: case S_COMP: return op;   /* S_COMP: the component record passed in `op` (md_comp_params) */
    default: return &C.pg[src - S_CTL_P0];
    }
}

/* page 2 (file_ctrl) of a part written by X9 (record +0x48 major 0x12) has another layout than the 2017 struct the
   tables describe: measured on BRACKET4.mcx-9 vs mc-test01.mcam - the NC path is at +0x14 (2017: +6) and the path
   strings are 0x102 apart (2017: 0x104). Mastercam 2017 converts it on load: the converter is NOT DECODED, so only
   +0 / +2 (error_msg$, err_file$: equal in both, err_file$ = 1 agrees with TEST-MC.err) are used from such a page. */
static int x9_page2(int off) {
    return C.pg[2].p && C.pg[2].n > 0x48 && C.pg[2].p[0x48] < 0x13 && off >= 0x80 + 4;
}

static void rows(PList *l, const PrmRow *t, int nt, const Rec *op) {
    char s[0x800];
    for (int i = 0; i < nt; i++) {
        const PrmRow *w = &t[i];
        const Rec *r = src_rec(w->src, op);
        if (w->src == S_CTL_P2 && w->kind != K_CONST && x9_page2(w->off)) { l->missing += w->n; continue; }
        if (w->kind == K_CONST) { add_num(l, w->code, strtod(w->lit, NULL)); continue; }
        if (w->kind == K_LIT) { add_str(l, w->code, w->lit); continue; }
        if (w->src == S_CTL_BASE && w->kind == K_NUM) {
            /* control_type (CCNCControl +0x2e94, GetMainPage @180037f90): the constructor memsets it (mccontrol_all.c
               line 26964), ControlDefaults @1800338c0 zeroes +0..+0xf and +0x8c, and the part's sub 23 record only
               supplies the manufacturer string +0x10 (ReadControlTypePostFromDB -> SetMainPageManufacturer); nothing
               else writes it, so every numeric field is 0 */
            for (int k = 0; k < w->n; k++) add_num(l, w->code + k, 0.0);
            continue;
        }
        if (w->kind == K_NUM) {
            static const int esz[] = { 1, 1, 2, 2, 4, 4, 4, 8, 1 };
            for (int k = 0; k < w->n; k++) {
                double v;
                if (field(r, w->off + k * esz[w->ct], w->ct, &v)) add_num(l, w->code + k, v); else l->missing++;
            }
        } else if (w->kind == K_STR) {
            if (cstrf(r, w->off, s, sizeof s)) add_str(l, w->code, s); else l->missing++;
        } else if (w->kind == K_CHR) {
            /* CString(char, 1) (Ordinal_301): a NUL char gives a 1-char string holding NUL = "" as C text (ours) */
            double v; if (field(r, w->off, T_I8, &v)) { s[0] = (char)(int)v; s[1] = 0; add_str(l, w->code, s); } else l->missing++;
        } else if (w->kind == K_UUIDL || w->kind == K_UUIDU) {
            if (uuidf(r, w->off, w->kind == K_UUIDU, s, sizeof s)) add_str(l, w->code, s); else l->missing++;
        }
    }
}

int mp_prm_md2(const McamFile *f, int ent, int dump, const char *sparameter, MpPrmCb cb, void *ctx);
static char *g15(char *b, size_t n, double v) { snprintf(b, n, "%.15g", v); return b; }   /* Ordinal_4604 "%.15lg" */

/* ReadCDInfoLoop @180122b90 / ReadGroupInfoLoop @180122f70 / ReadMDInfoLoopBase @180124070 (param_4 = header,
   param_5 = footer) / ReadOpInfoLoop @180124640: one call for the header, then numerics then strings, one per loop
   pass; when both lists are empty the do-while still makes one call with the header's code and string left in
   prmcode$ / sparameter$; the footer after the loop even when rd_exit$ stopped it. */
static int deliver(PList *l, int hdr, int hcode, const char *hstr, int ftr, double fval, MpPrmCb cb, void *ctx) {
    char b[64]; int code = hcode; const char *sp = hstr ? hstr : "";
    qsort(l->num, l->nn, sizeof *l->num, cmp_num); qsort(l->str, l->ns, sizeof *l->str, cmp_str);
    if (hdr && cb(ctx, hcode, sp) < 0) return 0;
    int i = 0, j = 0, stop = 0;
    char *last = strdup(sp);
    do {
        if (i < l->nn) { code = l->num[i].code; free(last); last = strdup(g15(b, sizeof b, l->num[i].v)); i++; }
        else if (j < l->ns) { code = l->str[j].code; free(last); last = strdup(l->str[j].s); j++; }
        int r = cb(ctx, code, last);
        if (r < 0) { free(last); return 0; }
        if (r > 0) stop = 1;
    } while ((i < l->nn || j < l->ns) && !stop);
    free(last);
    if (ftr && cb(ctx, 19999, g15(b, sizeof b, fval)) < 0) return 0;   /* PrmAppBase::SetDefaultFooter: 19999; value +0x54 = 0 */
    return 1;
}

int mp_prm_cd(const McamFile *f, MpPrmCb cb, void *ctx) {
    load(f);
    if (!C.ctl.p) return 0;               /* ReadCDInfo: no control -> AddRunGeneralMsg(0x2331, 0x100), 0 */
    PList l = { 0 };
    rows(&l, CTL_ROWS, sizeof CTL_ROWS / sizeof *CTL_ROWS, NULL);
    /* header: PrmControl::PrmControl with a group (pPostGroup): code 0x4e16 = 19990, the group's name (op_group +4);
       no group -> the empty PrmAppBase header (code left 0, "" : GetHeaderParameter @18000bbb0) */
    char name[0x105] = "";
    int hc = 0;
    if (C.grp.p) { cstrf(&C.grp, 4, name, sizeof name); hc = 19990; }
    int r = deliver(&l, 1, hc, name, 1, 0.0, cb, ctx);
    pl_free(&l);
    return r;
}

int mp_prm_group(const McamFile *f, MpPrmCb cb, void *ctx) {
    load(f);
    if (!C.grp.p) return 0;               /* ReadGroupInfo: no group -> message 0x2331 (0x400), 0 */
    PList l = { 0 };
    rows(&l, GRP_ROWS, sizeof GRP_ROWS / sizeof *GRP_ROWS, NULL);
    char name[0x105] = ""; cstrf(&C.grp, 4, name, sizeof name);   /* PrmGroup: header 0x4e02 = 19970, op_group +4 */
    int r = deliver(&l, 1, 19970, name, 1, 0.0, cb, ctx);
    pl_free(&l);
    return r;
}

int mp_prm_md(const McamFile *f, int ent, MpPrmCb cb, void *ctx) {
    load(f);
    if (!C.mach.p) return 0;              /* GetMachineObjectParam NULL -> CallMDInfoLoopBase message 0x2331 (0x200) */
    if (ent != 0) return mp_prm_md2(f, ent, 0, NULL, cb, ctx);   /* components / axis combinations (below) */
    PList l = { 0 };
    rows(&l, MCH_ROWS, sizeof MCH_ROWS / sizeof *MCH_ROWS, NULL);
    /* ReadMDInfo(0): CallMDInfoLoopBase(machine, 0, header 1, footer 1); PrmMachine header 0x4df8 = 19960 "MACHINE" */
    int r = deliver(&l, 1, 19960, "MACHINE", 1, 0.0, cb, ctx);
    pl_free(&l);
    return r;
}

int mp_prm_op(const McamFile *f, int op_index, MpPrmCb cb, void *ctx) {
    if (op_index < 0 || op_index >= f->nops || !f->ops[op_index].raw) return 0;   /* ReadOpInfo: OpByID failed -> 0x2331 */
    const Op *o = &f->ops[op_index];
    Rec op = { o->raw, o->raw_n };
    PList l = { 0 };
    rows(&l, OP_ROWS, sizeof OP_ROWS / sizeof *OP_ROWS, &op);
    int opc0 = (int16_t)rd16(o->raw + 0x6c);
    {   /* ParseOperation calls GetAssemblyIdInfo @18000de90: 0x3d9d = StringFromGUID2(this+0x1210 = record +0x1200):
           "{XXXXXXXX-XXXX-XXXX-XXXX-XXXXXXXXXXXX}" (upper case, braces); GetHolderIdnInfo @18000df50: 0x3d43 =
           (int) this+0x1220 = record +0x1210 (the holder's params when it is non-zero need Cnc::Tool::HolderGetHolder:
           NOT DECODED) */
        char g[64]; double hv;
        if (uuidf(&op, 0x1200, 1, g + 1, sizeof g - 2)) { g[0] = '{'; strcat(g, "}"); add_str(&l, 0x3d9d, g); }
        if (field(&op, 0x1210, T_I32, &hv)) add_num(&l, 0x3d43, hv);
    }
    /* the opcode-specific union: ParseOperation's case OP_CASE[opcode - 1] calls one builder on this+0x1238 = record
       +0x1228 and PrmAppBase::Add's it after the common rows (so a common code wins) */
    if ((unsigned)(opc0 - 1) <= 0x1c2u && OP_UNION_BUILDER[OP_CASE[opc0]]) {
        const int *rg = OP_UNION_RANGE[OP_UNION_BUILDER[OP_CASE[opc0]] - 1];
        rows(&l, OP_UNION_ROWS + rg[0], rg[1], &op);
    }
    /* header: ParseOperation's switch on OP_CASE[opcode - 1] (the byte map at 0x180012c50): code 10000 and the case's
       name; opcode - 1 > 0x1c2 or case 0x9c -> "Unknown Operation Type"; a case that sets no name leaves the empty
       header (code 0, "") */
    int opc = (int16_t)rd16(o->raw + 0x6c), hc = 0; const char *hn = "";
    if ((unsigned)(opc - 1) > 0x1c2u || OP_CASE[opc] == 0x9c) { hc = 10000; hn = "Unknown Operation Type"; }
    else if (OP_CASE_NAME[OP_CASE[opc]]) { hc = 10000; hn = OP_CASE_NAME[OP_CASE[opc]]; }
    /* footer value: SetPathType @18000e040 ORs +0x294c (= 2, ctor @18000dd80) into +0x54 for an opcode outside its path
       type ranges (1..0x38, 100..199, 0x1a0, 0x1b7..0x1b8, 0x3c..0x48, 0xc9..0xec, 0x4a..0x53, 0x12d..0x132) */
    unsigned u = (unsigned)opc0;
    int known = u - 1 < 0x38 || u - 100 < 100 || u == 0x1a0 || u - 0x1b7 < 2 || u - 0x3c < 0xd || u - 0xc9 < 0x24 ||
                u - 0x4a < 10 || u - 0x12d < 6;
    int r = deliver(&l, 1, hc, hn, 1, known ? 0.0 : 2.0, cb, ctx);
    pl_free(&l);
    return r;
}

/* ------------------------------------------------------------------------------------------------------------------
 * rd_md$ with rd_mch_ent_no$ != 0: the machine components and axis combinations of the active machine.
 *
 * Mastercam's model (every item cited where it is used below):
 *  - mccore's NCI writer (convert section, ~/mastercam-re/work/mp/mccore_nciwriters.c line 968) writes, before an op's
 *    999 line and only while CCNCMachine +0x10 is set, CCNCMachine::WriteComponentUIDsToNCI @18006eda0 (20600 lines, one
 *    per component of the tree, then it clears +0x10) and WriteAxisCombinationsToNCI @18006ec10 (20601 lines). Every
 *    CCNCMachine ctor (@180050450 / 660 / 830 / a70) sets +0x10 = 1, so a freshly loaded machine writes them before its
 *    first op. (The NCI port viewer/mp/nci_ascii.c does not write them yet: NOT DECODED there.)
 *  - mcpost reads them before the run: CPostStreams::BuildEnhancedToolTable -> CPostMachineInfo::DefaultEntUidDataMaps
 *    @1800b0c10 + ReadTraditionalAcAndComponets @1800ba450 -> BuildEntUidDataMaps @1800b0650 (20600: map +0x10 ent id ->
 *    {uid, label0, label1, name, diameter flag, rotary output}) and BuildAcEntUidDataMaps @1800b03e0 (20601: map +0x88
 *    axis-combo id -> {uid, "<mapped> <descriptor>"}). The port builds the same maps straight from the part records the
 *    lines are printed from (md_ncimaps); the defaults (ids -1..-6, uids "X".."C") never match a part id.
 *  - rd_md$ looks the uid up in mcmpparameters' PrmMachine (PrmMachine::PrmMachine @18003c390): AddComponent @18003d640
 *    (every component of the tree, keyed by MdComponentId::ToString = upper-case UuidToStringA, first insert wins ->
 *    PrmMachineComponent @18003ed10) and BuildAxisComboMap @18003d960 (CCNCMachine::MakeAxisComboList @18006b370 ->
 *    PrmPostAxisComboType @1800404f0).
 * Part records (ASSOC 0x4000; subtypes measured on mc-test01.mcam, BRACKET4.mcx-9 and the multiaxis samples):
 *  - machine (sub 22) = CCNCMachine - 0x70 (InitFromDb @180057e30 copies the record +0x68.. to object +0xd8): Type =
 *    object +0xd8 = record +0x68 (CCNCMachine::Type @18007bb20), the tree root id = object +0xf08 = record +0xe98
 *    (InitFromDb -> BuildComponentTreeFromDb(machine, +0xf08)), the axis-combination list id = AxisComboList_ent_idn
 *    @180061a20 = object +0xf14 = record +0xea4 (InitAxisCombinationsFromDb @1800628d0: a sub 15 list of combo ids).
 *  - component (sub 12, 0xa78 bytes): CMachineComponent::Params @object +0x20 = record +0x68 (0xa10 bytes; object X =
 *    record X + 0x48): Name +0x68, Type +0xe4, Ent_idns @object +0x250 = record +0x298 {self, next sibling +0x29c,
 *    previous sibling +0x2a0, first child +0x2a4} (measured: self = the record's entity id; the links reproduce the
 *    machine tree), uid = MdComponentId(object +0x238) = record +0x280 (CMachineComponent::InitUid @18008d200),
 *    UParams = Params +0x4a0 = record +0x508 (CLinearAxisComponent / CRotaryAxisComponent::UParams).
 *  - id list (sub 15): +0x68 count, +0x70 i32 ids (NCI agent, viewer/mp/nci_ascii.c).
 *  - axis combination (sub 26, 0x1ef8 bytes): Name (object +8) = record +0x68, uid MdComponentId(object +0x1df8) =
 *    record +0x1e58 (CAxisCombination::InitUid @180014830; object X = record X + 0x60: measured, the GUIDs are of the
 *    components' family), groups 0 / 1 (Group @180014440, object +0x3d18) = sub 13 ids at record +0x1e40 / +0x1e44,
 *    component lists 0 / 1 (CompList @1800126a0, object +0x3d30 + 0x28 i) = sub 15 ids at record +0x1e48 / +0x1e4c
 *    (measured; list 2 = WireUpperGuideComps is not in the record: empty here, NOT DECODED for wire machines).
 *  - component group (sub 13): +0xe4 = its CComponentGroupParams record (sub 21) id (measured); sub 21: Class (object
 *    +8) = record +0x68, Type (object +0xc, CComponentGroupParams::Type @1800a3b20) = record +0x6c (measured: the Table
 *    group's params have class 1, the spindle group's class 2). The GetNext @+0xd8 chain is not in the record: one
 *    params record per group (NOT DECODED beyond that).
 * ------------------------------------------------------------------------------------------------------------------ */
enum { MD_MAXC = 512, MD_MAXA = 64, MD_MAXL = 64 };
typedef struct { const Rec *r; int id, type; } MdComp;
typedef struct {
    const Rec *r; int id;
    int list[2][MD_MAXL], nlist[2];      /* the two component lists (ids, as stored) */
    int part, tool;                      /* PartComps / ToolComps list index, -1 = none */
    int circ[2 * MD_MAXL], ncirc;        /* MakePostCircuit @180015cf0: PartComps reversed, then ToolComps */
    int mapped, valid;                   /* IsMapped @180014940, IsValidForCutting @180014c20 (-1 = NOT DECODED) */
} MdAc;
static struct { int ok, type; MdComp comp[MD_MAXC]; int ncomp; MdAc ac[MD_MAXA]; int nac; } M;

static int i32(const Rec *r, int off) { double v; return field(r, off, T_I32, &v) ? (int)v : 0; }
static const Rec *md_rec(int sub, int id) {
    if (id == 0) return NULL;
    for (int i = 0; i < C.nmd; i++) if (C.mdsub[i] == sub && (int32_t)rd32(C.md[i].p + 0x34) == id) return &C.md[i];
    return NULL;
}
static const Rec *md_comp_rec(int id) { const Rec *r = md_rec(12, id); return r && r->n >= 0xa78 ? r : NULL; }
static int md_comp_type(const Rec *r) { return i32(r, 0xe4); }               /* CMachineComponent::Type = Params +0x7c */
/* the ids of a sub 15 list */
static int md_list(int id, int *out, int max) {
    const Rec *l = md_rec(15, id); if (!l) return 0;
    int n = i32(l, 0x68), k = 0;
    for (int i = 0; i < n && k < max && 0x70 + 4 * (uint32_t)(i + 1) <= l->n; i++) out[k++] = i32(l, 0x70 + 4 * i);
    return k;
}
/* PrmMachine::AddComponent @18003d640 / CCNCMachine::WriteComponentUIDToNCI @18006ecc0: the node, then each child
   (IMdComponent vtable +0x50 = first child, +0x70 = next sibling) recursively; in the record: first child +0x2a4,
   next sibling +0x29c (measured, see above) */
static void md_tree(int id, int depth) {
    for (; id > 0 && M.ncomp < MD_MAXC && depth < 64; ) {
        const Rec *r = md_comp_rec(id); if (!r) return;
        for (int i = 0; i < M.ncomp; i++) if (M.comp[i].id == id) return;         /* ours: a cycle guard */
        M.comp[M.ncomp++] = (MdComp){ r, id, md_comp_type(r) };
        md_tree(i32(r, 0x2a4), depth + 1);
        id = i32(r, 0x29c);
    }
}
static const MdComp *md_comp(int id) { for (int i = 0; i < M.ncomp; i++) if (M.comp[i].id == id) return &M.comp[i]; return NULL; }
/* CAxisCombination::CompListIsPart @1800126e0: the list's last component has a type in 100..108;
   CompListIsTool @1800127a0: 200..207 or 300..307 */
static int md_last_type(const MdAc *a, int i) {
    if (a->nlist[i] < 1) return -1;
    const Rec *r = md_comp_rec(a->list[i][a->nlist[i] - 1]); return r ? md_comp_type(r) : -1;
}
static int md_is_part(const MdAc *a, int i) { int t = md_last_type(a, i); return t > 99 && t < 0x6d; }
static int md_is_tool(const MdAc *a, int i) { int t = md_last_type(a, i); return (t >= 200 && t <= 0xcf) || (t >= 300 && t <= 0x133); }
/* CComponentGroup::IsClass(c, 0) @1800a08b0 over the group's params (one record, see above) */
static int md_group_params(int gid, int *cls, int *type) {
    const Rec *g = md_rec(13, gid); if (!g) return 0;
    const Rec *p = md_rec(21, i32(g, 0xe4)); if (!p) return 0;
    *cls = i32(p, 0x68); *type = i32(p, 0x6c); return 1;
}

static void md_build(const McamFile *f) {
    (void)f;
    if (C.mdok) return;
    C.mdok = 1; memset(&M, 0, sizeof M);
    if (!C.mach.p) return;
    M.ok = 1;
    M.type = i32(&C.mach, 0x68);
    md_tree(i32(&C.mach, 0xe98), 0);
    int ids[MD_MAXA]; int n = md_list(i32(&C.mach, 0xea4), ids, MD_MAXA);
    for (int k = 0; k < n && M.nac < MD_MAXA; k++) {
        const Rec *r = md_rec(26, ids[k]);
        if (!r || r->n < 0x1e68) continue;
        MdAc *a = &M.ac[M.nac++]; memset(a, 0, sizeof *a);
        a->r = r; a->id = ids[k];
        for (int i = 0; i < 2; i++) a->nlist[i] = md_list(i32(r, 0x1e48 + 4 * i), a->list[i], MD_MAXL);
        /* PartComps @180017160 / ToolComps @180018a40: list 0 if it qualifies, else list 1 */
        a->part = md_is_part(a, 0) ? 0 : md_is_part(a, 1) ? 1 : -1;
        a->tool = md_is_tool(a, 0) ? 0 : md_is_tool(a, 1) ? 1 : -1;
        /* MakePostCircuit(CObArray) @180015cf0: PartComps from the last to the first, then ToolComps in order; then
           MakePostCircuit(CArray<long>) @180015c00 maps each (non-NULL) component to Ent_idns()[0] */
        if (a->part >= 0) for (int i = a->nlist[a->part] - 1; i >= 0; i--) if (md_comp_rec(a->list[a->part][i])) a->circ[a->ncirc++] = a->list[a->part][i];
        if (a->tool >= 0) for (int i = 0; i < a->nlist[a->tool]; i++) if (md_comp_rec(a->list[a->tool][i])) a->circ[a->ncirc++] = a->list[a->tool][i];
        /* IsMapped @180014940: one of Group(0..(Type == 5) + 1) has CComponentGroup::IsMapped @1800a0d30 =
           IsClass(0x65) | IsClass(100) */
        for (int g = 0; g < (M.type == 5) + 2 && g < 2; g++) {
            int cls, ty;
            if (md_group_params(i32(r, 0x1e40 + 4 * g), &cls, &ty) && (cls == 0x65 || cls == 100)) a->mapped = 1;
        }
        if (M.type == 5) a->mapped = -1;                 /* wire: Group(2) is not in the record - NOT DECODED */
        /* IsValidForCutting @180014c20 */
        a->valid = 0;
        if (a->part >= 0 && a->tool >= 0) {
            if (M.type == 5 || M.type == 2) a->valid = -1;  /* wire branch (LinearAxis WCSAxis / MachineAxis test) and the
                                                             lathe op 0x3d (op_is_multiax jump table) - NOT DECODED */
            else {
                /* FindListComponentsByType(i = 0..2, 4) and, for Type 1 / 3, (i, 5); list 2 is empty (see above);
                   AxesTo_machine_axis_data @180066990: linear WCSAxis (UParams +0 @1800a9c60) 1/7 -> [1], 2/8 -> [2],
                   3/9 -> [3]; rotary WCSAxis (UParams +0x7c @1800afcd0) -> [4] / [5] / [6] */
                int cnt[7] = { 0 };
                for (int pass = 0; pass < 2; pass++) {
                    int want = pass ? 5 : 4;
                    if (pass && !(M.type == 1 || M.type == 3)) break;
                    for (int i = 0; i < 2; i++) for (int j = 0; j < a->nlist[i]; j++) {
                        const Rec *c = md_comp_rec(a->list[i][j]);
                        if (!c || md_comp_type(c) != want) continue;
                        int w = i32(c, want == 4 ? 0x508 : 0x584), base = want == 4 ? 0 : 3;
                        if (w == 1 || w == 7) cnt[base + 1]++; else if (w == 2 || w == 8) cnt[base + 2]++; else if (w == 3 || w == 9) cnt[base + 3]++;
                    }
                }
                /* EnoughMachineAxes @1800689a0 with op 1 (Type != 2 / 5): op_is_multiax(1) = 0 (mccore @1800c6700:
                   op - 28 > 0x7e), op_is_caxis(1) = 0 (@1800c5c90: op - 50 <= 7), op_is_mill(1) = 1 (@1800c6150:
                   op <= 0x39) -> the mill test, transcribed */
                int x = cnt[1], y = cnt[2], z = cnt[3], aa = cnt[4], b = cnt[5], c = cnt[6];
                int fail = ((x == 0 || y == 0 || z == 0) && (aa == 0 || b == 0 || c == 0)) && (x == 0 || b == 0 || c == 0) &&
                           (y == 0 || aa == 0 || c == 0) && (z == 0 || aa == 0 || b == 0) &&
                           (x == 0 || ((y == 0 || (aa == 0 && b == 0)) && (x == 0 || z == 0 || (aa == 0 && c == 0)))) &&
                           (y == 0 || z == 0 || (b == 0 && c == 0));
                a->valid = !fail;
            }
        }
    }
}
static const MdAc *md_ac(int id) { for (int i = 0; i < M.nac; i++) if (M.ac[i].id == id) return &M.ac[i]; return NULL; }

/* ---- the NCI uid maps (20600 / 20601 lines -> CPostMachineInfo maps +0x10 / +0x88) */
/* 20600 (CMachineComponent::WriteUIDToNCI @180090380: skipped for Type 2; CLinearAxisComponent @1800a9c70 and
   CRotaryAxisComponent @1800afcf0 always write): "%d %s \"%s\" \"%s\" %s" = id, uid, AxisLabel(0), AxisLabel(1), name */
static int md_nci_comp(int id) {
    const MdComp *c = md_comp(id);
    return c && !(c->type == 2);
}
/* 20601 (CAxisCombination::WriteToNCI @180018df0 via WriteAxisCombinationsToNCI @18006ec10: the combinations with
   !IsMapped and IsValidForCutting; a mapped combination's MappedAxisCombo is written too - NOT DECODED, so a
   combination whose flags are NOT DECODED (-1) is reported, not delivered): 1 = in the map, 0 = not, -1 = NOT DECODED */
static int md_nci_ac(const MdAc *a) {
    if (!a) return 0;
    if (a->mapped < 0 || a->valid < 0) return -1;
    return !a->mapped && a->valid;
}
/* GetUidFromUidInfo @1800b2f50 -> the uid; PrmMachine::GetComponentPointer @18003d810 (map keyed by uid, the first
   AddComponent of a uid wins): the component whose params are delivered */
static const MdComp *md_comp_by_uid_of(int id) {
    const MdComp *c = md_comp(id); if (!c) return NULL;
    for (int i = 0; i < M.ncomp; i++)
        if (!memcmp(M.comp[i].r->p + 0x280, c->r->p + 0x280, 16)) return &M.comp[i];
    return c;
}

/* ---- PrmMachineComponent::PrmMachineComponent @18003ed10 (param_2 = 0 from AddComponent: no 19958/19959 in the map) */
typedef struct { int type; const char *name; } MdTName;
static const MdTName MD_TNAME[] = {          /* the ctor's switch on Type: header (0x4df8 = 19960, name) */
    { 1, "STOCK_COMPONENT" }, { 2, "MISC_COMPONENT" }, { 3, "MACHINE_BASE_COMPONENT" }, { 4, "LINEAR_AXIS_COMPONENT" },
    { 5, "ROTARY_AXIS_COMPONENT" }, { 6, "GUIDE_BUSHING_COMPONENT" }, { 100, "RECT_TABLE_COMPONENT" },
    { 0x65, "ROUND_TABLE_COMPONENT" }, { 0x66, "WIRE_TABLE_COMPONENT" }, { 0x67, "FIXTURE_COMPONENT" },
    { 0x68, "VISE_COMPONENT" }, { 0x6a, "CHUCK_COMPONENT" }, { 0x6b, "CHUCK_JAWS_COMPONENT" }, { 0x6c, "COLLET_COMPONENT" },
    { 0xc9, "TOOL_COMPONENT" }, { 0xcb, "MULTI_HEAD_COMPONENT" }, { 0xcc, "MH_PIGGYBACK_COMPONENT" },
    { 0xcd, "WIRE_UPPER_GUIDE_COMPONENT" }, { 0xce, "WIRE_LOWER_GUIDE_COMPONENT" }, { 0x12d, "TOOL_SPINDLE_COMPONENT" },
    { 0x12e, "MULTI_TOOL_COMPONENT" }, { 0x12f, "TURRET_COMPONENT" }, { 0x131, "DRILL_BLOCK_COMPONENT" },
    { 0x132, "GANG_TOOL_COMPONENT" }, { 400, "ATC_COMPONENT" }, { 0x191, "TAILSTOCK_COMPONENT" },
    { 0x192, "LATHE_CENTER_COMPONENT" }, { 0x193, "STEADYREST_COMPONENT" },
};
/* the ctor's common part (record offsets = object offset - 0x48, Params = record +0x68; the ctor's GetParams copy
   local_a58 = Params, so local_X = Params + (0xa58 - X)) */
static const PrmRow MD_COMMON[] = {
    { 0x4331, K_STR, T_CHAR, S_COMP, 0x68, 1, "", "Name() = object +0x20" },
    { 0x4332, K_NUM, T_I32, S_COMP, 0xe0, 1, "", "(double)local_9e0 = Params +0x78" },
    { 0x4333, K_NUM, T_I32, S_COMP, 0xe4, 1, "", "Type() = Params +0x7c" },
    { 0x4334, K_NUM, T_U8, S_COMP, 0xe8, 1, "", "Color() = object +0xa0" },
    { 0x4337, K_NUM, T_F64, S_COMP, 0xf0, 3, "", "RefPt() = object +0xa8 (PrmAppBase::Add(int, p_3d))" },
    { 0x433a, K_NUM, T_F64, S_COMP, 0x108, 3, "", "AnchorPt() = object +0xc0" },
    { 0x433d, K_NUM, T_F64, S_COMP, 0x120, 3, "", "InitPt() = object +0xd8" },
    { 0x4340, K_NUM, T_F64, S_COMP, 0x138, 9, "", "InitXform() = object +0xf0 (matrix_33)" },
    { 0x4349, K_NUM, T_F64, S_COMP, 0x180, 9, "", "CurXform() = object +0x138" },
    { 0x4352, K_NUM, T_F64, S_COMP, 0x1c8, 3, "", "CurPos() = object +0x180" },
    /* 0x4564 ChordTol (hand: max(Params +0x178, tol)) */
    { 0x4565, K_NUM, T_U8, S_COMP, 0x1e8, 1, "", "Transparency() = object +0x1a0" },
    /* 0x45fb InitTabPg = Params +0x181 = record +0x1e9 (hand: its clamp needs object +0xc28, NOT DECODED) */
    { 0x45fb, K_NUM, T_U8, S_COMP, 0x1e9, 1, "", "InitTabPg() = Params +0x181" },
    { 0x45fc, K_NUM, T_I16, S_COMP, 0x1ea, 1, "", "(int)local_8d6 = Params +0x182" },
    { 0x45fd, K_NUM, T_I8, S_COMP, 0x1ec, 1, "", "(int)local_8d4 = Params +0x184" },
    { 0x4566, K_UUIDU, T_CHAR, S_COMP, 0x280, 1, "", "MdComponentId::ToString(CopyUid) (r8 = 0 @18003d692)" },
    { 0x4355, K_NUM, T_I32, S_COMP, 0x2a8, 1, "", "Machine_ent_idn() = object +0x260" },
    { 0x442b, K_NUM, T_I8, S_COMP, 0x2ac, 1, "", "HideInMW() = object +0x264" },
    /* 0x4356 IsExpanded(0) = (object +0x265 & DlgFlagToMask(0) = 1) != 0 (hand) */
    { 0x4357, K_NUM, T_I32, S_COMP, 0x2b0, 1, "", "GeoType() = Params +0x248" },
};
static int md_comp_params(const MdComp *c, PList *l, int *hcode, const char **hname) {
    const Rec *r = c->r;
    rows(l, MD_COMMON, 4, r);                                   /* 0x4331 .. 0x4334 (insert order kept) */
    rows(l, MD_COMMON + 4, 6, r);
    double v;
    /* CMachineComponent::ChordTol @180088430: Params +0x178 raised to mccore's tol when below it (tol = 5e-05, the
       static value of mccore ?tol, formats/mp_engine.md "ASCII NCI") */
    if (field(r, 0x1e0, T_F64, &v)) add_num(l, 0x4564, v < 5e-05 ? 5e-05 : v); else l->missing++;
    rows(l, MD_COMMON + 10, 7, r);
    if (field(r, 0x2ad, T_U8, &v)) add_num(l, 0x4356, ((int)v & 1) != 0); else l->missing++;   /* IsExpanded(0) */
    rows(l, MD_COMMON + 17, 1, r);
    /* the geometry struct: switch on GeoType 2..7 (SolidGeo = object +0x270 = record +0x2b8) */
    int geo = i32(r, 0x2b0);
    for (size_t k = 0; k < sizeof GEO_RANGE / sizeof *GEO_RANGE; k++)
        if (GEO_RANGE[k][0] == geo) rows(l, GEO_ROWS + GEO_RANGE[k][1], GEO_RANGE[k][2], r);
    /* the type struct */
    for (size_t k = 0; k < sizeof COMP_RANGE / sizeof *COMP_RANGE; k++)
        if (COMP_RANGE[k][0] == c->type) rows(l, COMP_ROWS + COMP_RANGE[k][1], COMP_RANGE[k][2], r);
    if (c->type == 0x12d) {   /* FUN_180045110: 0x45cc = MdComponentId(param_2 + 8).ToString(false) (objdump 180045176) */
        char g[64]; if (uuidf(r, 0x510, 1, g, sizeof g)) add_str(l, 0x45cc, g); else l->missing++;
    }
    if (c->type == 0x193) {   /* STEADYREST: + 0x45ba = (double)local_540 = UParams +0x78 */
        if (field(r, 0x580, T_I32, &v)) add_num(l, 0x45ba, v); else l->missing++;
    }
    *hcode = 19960; *hname = "UNIDENTIFIED_COMPONENT";               /* the switch's default */
    for (size_t k = 0; k < sizeof MD_TNAME / sizeof *MD_TNAME; k++) if (MD_TNAME[k].type == c->type) *hname = MD_TNAME[k].name;
    return 1;
}

/* ---- PrmPostAxisComboType @1800404f0 from CCNCMachine::MakeAxisComboList @18006b370 (post_axis_combo_type: +0 Id,
   +4.. the first 12 post-circuit ids, +0x34 Name (_mbsnbcpy_s 0x78)); tool / part group types from BuildAxisComboMap
   @18003d960 (ToolGroup / PartGroup -> ParamList -> Type, -1 without one). In the PrmMachine map only when the circuit
   is not empty. Header 19960 "MACHINE_AXIS", 19959 = Id, 19958 = -1. */
static int md_group_type(const MdAc *a, int tool) {
    /* ToolGroup @180018a90 / PartGroup @1800171b0 of a not mapped combination: GroupByClass(2 / 1) @180014480 =
       Group(0) when list 0 is the tool (part) list, else Group(1) when list 1 is */
    int g = tool ? (md_is_tool(a, 0) ? 0 : md_is_tool(a, 1) ? 1 : -1) : (md_is_part(a, 0) ? 0 : md_is_part(a, 1) ? 1 : -1);
    int cls, ty;
    if (g < 0 || !md_group_params(i32(a->r, 0x1e40 + 4 * g), &cls, &ty)) return -1;
    return ty;
}
static void md_ac_params(const MdAc *a, PList *l) {
    add_num(l, 0x4513, a->id);
    for (int i = 0; i < 12; i++) add_num(l, 0x4514 + i, i < a->ncirc ? a->circ[i] : 0);
    char nm[0x78]; cstrf(a->r, 0x68, nm, sizeof nm);
    add_str(l, 0x4520, nm);
    add_num(l, 0x463d, md_group_type(a, 1));
    add_num(l, 0x463e, md_group_type(a, 0));
}

/* ---- delivery: ReadMDInfoLoop @1801238c0 (components, header via ReadMDComponentHeader @180123370) and
   ReadMDInfoLoopAC @180123c10 (combinations): rd_exit$ = 0; [header; 19959; 19958]; numerics then strings (one call
   at least: an empty object calls once with prmcode 0 and the last sparameter$); [footer]. Returns 0 when a postblock
   call failed. */
static int md_deliver(PList *l, int hdr, int hcode, const char *hname, double v59, double v58, int ftr, MpPrmCb cb, void *ctx) {
    char b[64]; char *last = strdup("");
    qsort(l->num, l->nn, sizeof *l->num, cmp_num); qsort(l->str, l->ns, sizeof *l->str, cmp_str);
    int ok = 1;
    if (hdr) {
        if (cb(ctx, hcode, hname) < 0) { ok = 0; goto out; }
        if (cb(ctx, 19959, g15(b, sizeof b, v59)) < 0) { ok = 0; goto out; }   /* GetHeaderG19959, "%.15lg" */
        if (cb(ctx, 19958, g15(b, sizeof b, v58)) < 0) { ok = 0; goto out; }   /* GetHeaderG19958 */
        free(last); last = strdup(b);
    }
    int i = 0, j = 0, code = 0, stop = 0;
    do {
        if (i < l->nn) { code = l->num[i].code; free(last); last = strdup(g15(b, sizeof b, l->num[i].v)); i++; }
        else if (j < l->ns) { code = l->str[j].code; free(last); last = strdup(l->str[j].s); j++; }
        int r = cb(ctx, code, last);
        if (r < 0) { ok = 0; goto out; }
        if (r > 0) stop = 1;
    } while ((i < l->nn || j < l->ns) && !stop);
    if (ftr && cb(ctx, 19999, g15(b, sizeof b, 0.0)) < 0) ok = 0;      /* PrmAppBase footer 19999, value +0x54 = 0 */
out:
    free(last);
    return ok;
}
/* CallMDInfoLoop @1801219b0 for a component id (NULL param -> message 0x2331, 0) */
static int md_call_comp(int id, int hdr, int ftr, MpPrmCb cb, void *ctx) {
    const MdComp *c = md_comp_by_uid_of(id);
    if (!c) return 0;
    PList l = { 0 }; int hc; const char *hn;
    md_comp_params(c, &l, &hc, &hn);
    int r = md_deliver(&l, hdr, hc, hn, c->id, c->type, ftr, cb, ctx);   /* 19959 = local_828 = Params +0x230 = Ent_idns()[0] */
    pl_free(&l);
    return r;
}
/* CallMDInfoLoopAC @180121a40 (GetMachineAComboParam: the combination must have a post circuit) */
static int md_call_ac(const MdAc *a, int hdr, int ftr, MpPrmCb cb, void *ctx) {
    if (!a || a->ncirc < 1) return 0;
    PList l = { 0 };
    md_ac_params(a, &l);
    int r = md_deliver(&l, hdr, 19960, "MACHINE_AXIS", a->id, -1.0, ftr, cb, ctx);
    pl_free(&l);
    return r;
}
/* CallMDInfoLoopAcComponents @180121ad0: params 0x4513..0x451f of the combination; each value whose component uid
   (GetUidFromUidInfo) has 36 characters -> CallMDInfoLoop(header, no footer) (its result is ignored); then
   ReadMDComponentFooter @180123280 of the last one found (no call when none) */
static int md_call_ac_components(const MdAc *a, MpPrmCb cb, void *ctx) {
    if (!a || a->ncirc < 1) return 0;                     /* NULL param: message 0x2331 (0x200), 0 */
    int ids[13] = { a->id }, last = 0;
    for (int i = 0; i < 12; i++) ids[i + 1] = i < a->ncirc ? a->circ[i] : 0;
    for (int i = 0; i < 13; i++) {
        if (!md_nci_comp(ids[i])) continue;               /* not in the 20600 map: GetUidFromUidInfo NULL */
        last = ids[i];
        md_call_comp(ids[i], 1, 0, cb, ctx);
    }
    if (last && md_comp_by_uid_of(last)) { char b[64]; if (cb(ctx, 19999, g15(b, sizeof b, 0.0)) < 0) return 0; }
    return 1;
}
/* LoopOnAxisComponentInfo @1800b9440: the 20600 map (ascending ids) entries with id > 0, stable-sorted by
   (rotary output short >> 4): BuildEntUidDataMaps stores GetDiameterAndRotaryOutputFromAxisId @1800b2370 = (short)
   (CCNCMachine::GetRotaryOutputFromAxisId @180062780 + 1), negated when GetRotaryCwOutputFromAxisId @180062700;
   rotary (Type 5): AxisOutputType = UParams +0xb8 (record +0x5c0), CWAxis = UParams +0x84 (record +0x58c); others -1 */
static int md_rot_key(const MdComp *c) {
    short k = 0;
    if (c->type == 5) {
        k = (short)(i32(c->r, 0x5c0) + 1);
        double cw; if (field(c->r, 0x58c, T_I8, &cw) && cw != 0) k = (short)-k;
    }
    return k >> 4;
}

int mp_prm_md2(const McamFile *f, int ent, int dump, const char *sparameter, MpPrmCb cb, void *ctx) {
    load(f);
    if (!C.mach.p) return 0;
    if (ent == 0) return mp_prm_md(f, 0, cb, ctx);
    md_build(f);
    if (ent == -2) {
        /* FindMachineData(name, 0, 0) @180121ce0: LoopOnAxisComboInfo, compare sparameter$ with the entry's second
           string = the 20601 line after "<id> <uid> " ("<IsMapped> <Descriptor>", Descriptor @180013280 = Name for a
           not mapped combination), Ordinal_2863 (case sensitivity NOT DECODED: ours exact) */
        const char *sp = sparameter ? sparameter : "";
        for (int i = 0; i < M.nac; i++) {
            const MdAc *a = &M.ac[i]; int in = md_nci_ac(a);
            if (in < 0) return -1;
            if (!in) continue;
            char d[0x100], nm[0x78]; cstrf(a->r, 0x68, nm, sizeof nm);
            snprintf(d, sizeof d, "%d %s", a->mapped, nm);
            if (!strcmp(sp, d)) return md_call_ac_components(a, cb, ctx);
        }
        /* then LoopOnAxisComponentInfo: the component whose name (the text after the 4th '"') equals it */
        for (int i = 0; i < M.ncomp; i++) {
            if (!md_nci_comp(M.comp[i].id)) continue;
            char nm[0x100]; cstrf(M.comp[i].r, 0x68, nm, sizeof nm);
            if (!strcmp(sp, nm)) return md_call_comp(M.comp[i].id, 1, 1, cb, ctx);
        }
        return 1;                                         /* nothing found: success, no calls */
    }
    if (ent == -1) {
        /* base without footer, every combination (header, no footer), every component (header, no footer), one
           footer after the last component */
        PList l = { 0 };
        rows(&l, MCH_ROWS, sizeof MCH_ROWS / sizeof *MCH_ROWS, NULL);
        int r = deliver(&l, 1, 19960, "MACHINE", 0, 0.0, cb, ctx);
        pl_free(&l);
        if (!r) return 0;
        int ids[MD_MAXA], n = 0;
        for (int i = 0; i < M.nac; i++) { int in = md_nci_ac(&M.ac[i]); if (in < 0) return -1; if (in) ids[n++] = M.ac[i].id; }
        for (int i = 1; i < n; i++) for (int k = i; k > 0 && ids[k] < ids[k - 1]; k--) { int t = ids[k]; ids[k] = ids[k - 1]; ids[k - 1] = t; }
        for (int i = 0; i < n; i++) if (!md_call_ac(md_ac(ids[i]), 1, 0, cb, ctx)) return 0;
        int cid[MD_MAXC], nc = 0;
        for (int i = 0; i < M.ncomp; i++) if (md_nci_comp(M.comp[i].id) && M.comp[i].id > 0) cid[nc++] = M.comp[i].id;
        for (int i = 1; i < nc; i++) for (int k = i; k > 0 && cid[k] < cid[k - 1]; k--) { int t = cid[k]; cid[k] = cid[k - 1]; cid[k - 1] = t; }
        int ord[MD_MAXC], no = 0;                          /* insertion before the first entry with a greater key */
        for (int i = 0; i < nc; i++) {
            int k = md_rot_key(md_comp(cid[i])), at = no;
            for (int j = 0; j < no; j++) if (k < md_rot_key(md_comp(ord[j]))) { at = j; break; }
            memmove(ord + at + 1, ord + at, (size_t)(no - at) * sizeof *ord); ord[at] = cid[i]; no++;
        }
        int last = 0;
        for (int i = 0; i < no; i++) { if (!md_call_comp(ord[i], 1, 0, cb, ctx)) return 0; last = ord[i]; }
        if (last) { char b[64]; if (cb(ctx, 19999, g15(b, sizeof b, 0.0)) < 0) return 0; }
        return 1;
    }
    /* any other value: FindMachineData(|ent|, 1, 0) = GetAcUidFromUidInfo; < 0 or a dump read -> the combination's
       own params (CallMDInfoLoopAC, header + footer), > 0 -> its components (CallMDInfoLoopAcComponents); else
       FindMachineData(|ent|, 1, 1) = GetUidFromUidInfo -> the component (CallMDInfoLoop, header + footer); else
       success with no calls */
    int id = ent < 0 ? -ent : ent;
    const MdAc *a = md_ac(id);
    int in = md_nci_ac(a);
    if (in < 0) return -1;
    if (in) return (ent < 0 || dump) ? md_call_ac(a, 1, 1, cb, ctx) : md_call_ac_components(a, cb, ctx);
    if (md_nci_comp(id)) return md_call_comp(id, 1, 1, cb, ctx);
    return 1;
}

/* debugging / tests: the decoded machine model */
int mp_md_info(const McamFile *f, char *buf, size_t n) {
    load(f); md_build(f);
    size_t o = 0;
    o += (size_t)snprintf(buf + o, o < n ? n - o : 0, "machine type %d root %d combos list %d: %d components, %d combinations\n",
                          M.type, C.mach.p ? i32(&C.mach, 0xe98) : 0, C.mach.p ? i32(&C.mach, 0xea4) : 0, M.ncomp, M.nac);
    for (int i = 0; i < M.ncomp && o < n; i++) {
        char nm[64], g[64] = ""; cstrf(M.comp[i].r, 0x68, nm, sizeof nm); uuidf(M.comp[i].r, 0x280, 1, g, sizeof g);
        o += (size_t)snprintf(buf + o, o < n ? n - o : 0, "  comp %d type %d %-26s uid %s nci %d key %d\n", M.comp[i].id,
                              M.comp[i].type, nm, g, md_nci_comp(M.comp[i].id), md_rot_key(&M.comp[i]));
    }
    for (int i = 0; i < M.nac && o < n; i++) {
        const MdAc *a = &M.ac[i]; char nm[0x78]; cstrf(a->r, 0x68, nm, sizeof nm);
        o += (size_t)snprintf(buf + o, o < n ? n - o : 0, "  combo %d \"%s\" part list %d tool list %d mapped %d valid %d nci %d circuit",
                              a->id, nm, a->part, a->tool, a->mapped, a->valid, md_nci_ac(a));
        for (int k = 0; k < a->ncirc && o < n; k++) o += (size_t)snprintf(buf + o, o < n ? n - o : 0, " %d", a->circ[k]);
        if (o < n) o += (size_t)snprintf(buf + o, n - o, "\n");
    }
    return (int)o;
}

/* ------------------------------------------------------------------------------------------------------------------
 * InitialAssignFromMD @1800b8a80, the part before the feed rates (direct writes `*GetVarRef = v`, no
 * AssignOutputVariableReInit, no message; inside `x_mp_adv_func$ != 0`), for the first tool-table record
 * (CPostToolTable +0x18): its axis combination id = strt_tooltable +0x38 (BuildAddToolTableRecord @18015bb00:
 * (int) of an NCI value; the interpreter passes it as `axcombo`).
 *  matb1$ = the machine base matrix (tool table +0x198 -> CPostRunComponents::AddMachineBaseData @1801172f0 node, data
 *  +0x10 = the matrix) = GetAxisComboMachineMatrix @1800b1b10 when it succeeds;
 *  the axis order (GetAxisComboInfoAndAxisOrder @1800b16c0 -> CPostRunComponents::AddAxisComboAxisOrder, only when it
 *  returned 1): primary / secondary rotary = list1[3 + order[0 / 1]] -> its record (get_assoc_ent_ent_idn(0xc, id));
 *  when Type == 5: pri_/sec_limlo$ / limhi$ = +0x610 / +0x618, intlo$ / inthi$ = +0x5a0 / +0x5a8, limtyp$ =
 *  GetLimitType @1800b2650, rotaxis1/2$ and rotdir1/2$ = CalcAxisZeroAndDirection @1800b0ae0 (+0x584 WCS axis, +0x588
 *  zero-degree axis, +0x58c CW), and for the secondary nut_ang_pri$ = +0x598 when +0x58d != 0.
 * Combination 0 (no axis combination): DefaultEntUidDataMaps' order (ids -4 / -5: no record) -> nothing.
 * ------------------------------------------------------------------------------------------------------------------ */
/* CLinearAxisComponent::GetAxisVec(v, 0, 0) @1800a7fa0: AxisDir (UParams +0 @1800a77c0) 1/2/3 -> +X/+Y/+Z, 7/8/9 -> -X/-Y/-Z,
   else 0 */
static void md_axis_vec(const Rec *r, double v[3]) {
    int d = i32(r, 0x508);
    v[0] = v[1] = v[2] = 0;
    if (d == 1) v[0] = 1; else if (d == 2) v[1] = 1; else if (d == 3) v[2] = 1;
    else if (d == 7) v[0] = -1; else if (d == 8) v[1] = -1; else if (d == 9) v[2] = -1;
}
/* GetAxisComboMachineMatrix @1800b1b10: rows X / Y / Z from the linear axes (PartComps then ToolComps, in list order)
   by MachineAxis (UParams +0x198 = record +0x6a0) 1|7 / 2|8 / 3|9; after each, the missing third row = the cross product
   of the other two when two are known; 1 when three rows are known (or derived) */
static int md_machine_matrix(const MdAc *a, double m[9], int *rows_set) {
    unsigned bits = 0; int ok = 0;
    for (int k = 0; k < 9; k++) m[k] = 0;
    for (int s = 0; s < 2; s++) {
        int li = s == 0 ? a->part : a->tool;
        if (li < 0) continue;
        for (int i = 0; i < a->nlist[li]; i++) {
            const Rec *c = md_comp_rec(a->list[li][i]);
            if (!c || md_comp_type(c) != 4) continue;           /* __RTDynamicCast CLinearAxisComponent */
            int ma = i32(c, 0x6a0), row = -1;
            if (ma == 1 || ma == 7) { bits |= 1; row = 0; } else if (ma == 2 || ma == 8) { bits |= 2; row = 1; } else if (ma == 3 || ma == 9) { bits |= 4; row = 2; }
            if (row >= 0) md_axis_vec(c, m + 3 * row);
            double *r0 = m, *r1 = m + 3, *r2 = m + 6;
            if ((bits & 7) == 7) ok = 1;
            else if (!(bits & 1)) { if ((bits & 6) == 6) { r0[0] = r1[1] * r2[2] - r2[1] * r1[2]; r0[1] = r2[0] * r1[2] - r1[0] * r2[2]; r0[2] = r1[0] * r2[1] - r2[0] * r1[1]; ok = 1; } }
            else if (!(bits & 2)) { if (bits & 4) { r1[0] = r2[1] * r0[2] - r2[2] * r0[1]; r1[1] = r2[2] * r0[0] - r2[0] * r0[2]; r1[2] = r2[0] * r0[1] - r2[1] * r0[0]; ok = 1; } }
            else { r2[0] = r0[1] * r1[2] - r0[2] * r1[1]; r2[1] = r1[0] * r0[2] - r0[0] * r1[2]; r2[2] = r0[0] * r1[1] - r1[0] * r0[1]; ok = 1; }
        }
    }
    *rows_set = (int)bits;
    return ok;
}
/* CPostMath::eq_vec_tol_rev @1800c3640 against the rows of CPostMath::s_MatTopView (.data 0x1802bc790 = identity) */
static int md_eq_rev(const double *a, int axis, int *rev) {
    double b[3] = { axis == 0, axis == 1, axis == 2 }, t = 5e-08;
    *rev = 0;
    if (fabs(a[0] - b[0]) < t && fabs(a[1] - b[1]) < t && fabs(a[2] - b[2]) < t) return 1;
    if (fabs(a[0] + b[0]) < t && fabs(a[1] + b[1]) < t && fabs(a[2] + b[2]) < t) { *rev = 1; return 1; }
    return 0;
}
/* PlanarReversalFromMatrixVector @1800b9b80 */
static int md_planar(const double *row, short st[3]) {
    int rev, r = -1;
    if (st[0] == 0 && md_eq_rev(row, 0, &rev)) { st[0] = rev ? -1 : 1; r = 0; }
    if (st[1] == 0 && md_eq_rev(row, 1, &rev)) { st[1] = rev ? -1 : 1; r = 1; }
    if (st[2] == 0 && md_eq_rev(row, 2, &rev)) { st[2] = rev ? -1 : 1; r = 2; }
    return r;
}
/* MapMpTypeToAC @1800b9690 (rel = strt +0x48 shorts, flip = strt +0x51 flags) */
static int md_map_ac(int t, const short rel[3], const unsigned char flip[3]) {
    int idx = t == 1 || t == -1 ? 0 : t == 2 || t == -2 ? 1 : t == 3 || t == -3 ? 2 : -1;
    if (idx < 0) return t;
    int neg = t < 0; if (flip[idx]) neg = !neg;
    return (rel[idx] + 1) * (neg ? -1 : 1);
}
static int md_signed_axis(int a) { return a == 1 || a == 2 || a == 3 ? a : a == 7 ? -1 : a == 8 ? -2 : a == 9 ? -3 : 0; }   /* ConvertToSignedAxis @1800b0b90 */
/* GetDirectionAxis @1800b23f0, transcribed */
static int md_dir_axis(int p1, int p2, int cw) {
    if (p1 == 0) return 0;
    signed char s = (signed char)(abs(p1) - 2 + abs(p2));
    if (s == 1) {
        if (p2 == -2 || p2 == 1) return (!cw || p1 < 1) ? 3 : -3;
        if (p2 == -1 || p2 == 2) return (cw || p1 < 1) ? 3 : -3;
        return 0;
    }
    if (s == 2) {
        if (p2 == -3 || p2 == 1) return (!cw || p1 < 1) ? 2 : -2;
        if (p2 == -1 || p2 == 3) return (cw || p1 < 1) ? 2 : -2;
        return 0;
    }
    if (s == 3) {
        if (p2 == -3 || p2 == 2) return (!cw && p1 > 0) ? -1 : 1;
        if (p2 == -2 || p2 == 3) return (cw && p1 > 0) ? -1 : 1;
        return 0;
    }
    return 0;
}
/* GetLimitType @1800b2650 */
static int md_limit_type(double lo, double hi, double ilo, double ihi) {
    double d = fabs(hi - lo);
    if (d < 180.0) return 0;
    if (d < 180.0 || 360.0 <= d) { if (390.0 <= d || fabs(ihi - ilo) != 360.0) return 3; if (d != 360.0) return 2; }
    return 1;
}

int mp_md_rotary(const McamFile *f, int axcombo, MpOverride *out, int max) {
    load(f); md_build(f);
    static char src[32][96];
    int n = 0;
#define PUT(nm, val, s) do { if (n < max && n < 32) { snprintf(src[n], sizeof src[n], "%s", s); out[n] = (MpOverride){ nm, val, src[n], MPO_ADV | MPO_DIRECT, 0, 0, 0 }; } n++; } while (0)
    const MdAc *a = md_ac(axcombo);
    if (!a) return 0;                                       /* combination 0 / unknown: no record for the default ids */
    double m[9]; int rs;
    int okm = md_machine_matrix(a, m, &rs);
    if (!okm) return -1;      /* fewer than two linear axes: the matrix (local_b8) is not set - NOT DECODED */
    static const char *const MB[9] = { "matb1$[0]", "matb1$[1]", "matb1$[2]", "matb1$[3]", "matb1$[4]", "matb1$[5]", "matb1$[6]", "matb1$[7]", "matb1$[8]" };
    for (int k = 0; k < 9; k++) PUT(MB[k], m[k], "CPostMath::SetMatrix(matb1$, machine base matrix) (InitialAssignFromMD)");
    /* GetAxisComboInfoList @1800b1770: the components of PartComps (last to first) then ToolComps */
    int seq[2 * MD_MAXL], ns = 0;
    if (a->part >= 0) for (int i = a->nlist[a->part] - 1; i >= 0; i--) seq[ns++] = a->list[a->part][i];
    if (a->tool >= 0) for (int i = 0; i < a->nlist[a->tool]; i++) seq[ns++] = a->list[a->tool][i];
    long l1[6] = { 0 }, l2[6] = { 0 };
    int have = a->part >= 0 && a->tool >= 0;                 /* no PartComps / ToolComps: GetAxisComboInfoList returns 0 */
    for (int k = 0; k < 6; k++)                             /* param_3 = 1: slot k = MachineAxis k + 1 or k + 7 */
        for (int j = 0; j < ns; j++) {
            const Rec *c = md_comp_rec(seq[j]); if (!c) continue;
            int t = md_comp_type(c), ma;
            if (t == 5) ma = i32(c, 0x580);                 /* CRotaryAxisComponent::MachineAxis = UParams +0x78 */
            else if (t == 4) ma = i32(c, 0x6a0);            /* CLinearAxisComponent::MachineAxis = UParams +0x198 */
            else continue;
            if (ma == k + 1 || ma == k + 7) { l1[k] = seq[j]; break; }
        }
    for (int j = 0, k = 0; j < ns && k < 6; j++) {         /* param_3 = 0: the first six linear / rotary axes */
        const Rec *c = md_comp_rec(seq[j]); if (!c) continue;
        int t = md_comp_type(c); if (t == 4 || t == 5) l2[k++] = seq[j];
    }
    int any1 = 0, any2 = 0; for (int k = 0; k < 6; k++) { any1 |= l1[k] != 0; any2 |= l2[k] != 0; }
    if (!have || !any1 || !any2) for (int k = 0; k < 6; k++) l1[k] = l2[k] = -1 - k;   /* alOrderXyzAbc (.data 0x1802bbff8) */
    /* SetNumberAxisAndHeadOrderRotary @1800bb060 */
    short order[3] = { -1, -1, -1 }; int nr = 0;
    for (int k = 0; k < 6; k++) {
        if (!l2[k]) continue;
        for (int i = 0; i < 6; i++) if (l2[k] == l1[i]) { if (i >= 3 && nr < 3) order[nr++] = (short)(i - 3); break; }
    }
    /* GetAxisComboReversalRotationWorldRelations @1800b1f00 */
    short rel[3] = { 0, 0, 0 }, st[3] = { 0, 0, 0 }; unsigned char flip[3] = { 0, 0, 0 };
    int r0 = md_planar(m, st), r1 = r0 != -1 ? md_planar(m + 3, st) : -1, r2 = r1 != -1 ? md_planar(m + 6, st) : -1;
    if (r0 == -1 || r1 == -1 || r2 == -1) return n;         /* returns 0: no axis order is stored, no rotary assignment */
    rel[0] = (short)r0; rel[1] = (short)r1; rel[2] = (short)r2;
    for (int k = 0; k < 3; k++) flip[k] = st[rel[k]] == -1;
    static const char *const V[2][8] = {
        { "pri_limlo$", "pri_limhi$", "pri_intlo$", "pri_inthi$", "pri_limtyp$", "rotaxis1$", "rotdir1$", NULL },
        { "sec_limlo$", "sec_limhi$", "sec_intlo$", "sec_inthi$", "sec_limtyp$", "rotaxis2$", "rotdir2$", "nut_ang_pri$" } };
    for (int s = 0; s < 2; s++) {
        unsigned short o = (unsigned short)order[s];
        long id = o < 4 ? l1[3 + o] : 0;                    /* (ushort)strt +0x3c / +0x3e < 4 ? alStack_29c4[..] : 0 */
        const Rec *c = id > 0 ? md_comp_rec((int)id) : NULL;
        if (!c || md_comp_type(c) != 5) continue;
        double lo = 0, hi = 0, ilo = 0, ihi = 0, nut = 0, cwv = 0;
        field(c, 0x610, T_F64, &lo); field(c, 0x618, T_F64, &hi); field(c, 0x5a0, T_F64, &ilo); field(c, 0x5a8, T_F64, &ihi);
        char sb[96]; snprintf(sb, sizeof sb, "rotary component %ld (InitialAssignFromMD @1800b8a80)", id);
        PUT(V[s][0], lo, sb); PUT(V[s][1], hi, sb); PUT(V[s][2], ilo, sb); PUT(V[s][3], ihi, sb);
        PUT(V[s][4], md_limit_type(lo, hi, ilo, ihi), sb);
        field(c, 0x58c, T_I8, &cwv);
        int z = md_signed_axis(i32(c, 0x588));
        PUT(V[s][5], md_map_ac(z, rel, flip), sb);
        PUT(V[s][6], md_map_ac(md_dir_axis(md_signed_axis(i32(c, 0x584)), z, cwv != 0), rel, flip), sb);
        double nf; if (s == 1 && field(c, 0x58d, T_I8, &nf) && nf != 0 && field(c, 0x598, T_F64, &nut)) PUT(V[s][7], nut, sb);
    }
#undef PUT
    return n;
}

int mp_cd_seq(const McamFile *f, double *start, double *inc, double *max) {
    load(f);
    double v[3];
    for (int k = 0; k < 3; k++) if (!field(&C.pg[8], 0x80 + 8 * k, T_F64, &v[k])) return 0;
    *start = v[0]; *inc = v[1]; *max = v[2];
    return 1;
}

int mp_cd_quiet(const McamFile *f) {
    load(f);
    double v; return !x9_page2(0x80 + 0xd4a) && field(&C.pg[2], 0x80 + 0xd4a, T_I8, &v) && v != 0;   /* InitialAssignFromCD: fVar2 = file_ctrl[0xd4a] */
}

