static int pgv(int pg, int off, int ct, double *v) {
    if (pg == FIL && x9_page2(0x80 + off)) return 0;
    const Rec *r = pg == MCH ? &C.mach : &C.pg[pg];
    return field(r, pg == MCH ? off : 0x80 + off, ct, v);
}

int mp_cd_overrides(const McamFile *f, int product, MpOverride *out, int max) {
    (void)product;
    load(f);
    if (!C.mach.p || !C.ctl.p) return -1;   /* InitialAssignFromCD: no CCNCMachine::Control -> message 0x2331 (0x100) */
    static char src[sizeof OVR / sizeof *OVR][96];
    int n = 0;
    for (size_t i = 0; i < sizeof OVR / sizeof *OVR; i++) {
        const OvrRow *w = &OVR[i];
        double v = 0, a = 0, b = 0, c = 0, d = 0, e = 0, s = 0;
        int ok = 1;
        switch (w->how) {
        case V_RAW: ok = pgv(w->pg, w->off, w->ct, &v); break;
        case V_PLUS1: ok = pgv(w->pg, w->off, w->ct, &v); v += 1.0; break;                          /* (short) + 1.0 */
        case V_ARCOUT: ok = pgv(w->pg, w->off, w->ct, &v); v = v < 4 ? 0.0 : v - 3.0; break;       /* < 4 ? 0 : s - 3 */
        case V_EQ0: ok = pgv(w->pg, w->off, w->ct, &v); v = v == 0; break;                         /* (byte == 0) */
        case V_X001: ok = pgv(w->pg, w->off, w->ct, &v); v *= 0.01; break;                         /* (short) * 0.01 */
        case V_CONST1:
            if (w->off < 0 && w->pg == MCH) { v = 0.0; break; }                                    /* fr_min_ideg$ / mdeg$ */
            ok = pgv(NCP, 0x118, T_I8, &a) && pgv(NCP, 0x22c, T_I8, &b);                         /* bldnxtool$ */
            if (ok && !(a != 0 || b != 0)) continue;
            v = 1.0; break;
        case V_ARCCHECK:   /* (+2 !=0 ? 10) + (+0 != 0) + (+4 ? 100 + short(+0x684-0x67c... ) * 100) + (+3 ? 1000) + (+1 ? 10000) */
            ok = pgv(NCP, w->off, T_I8, &a) && pgv(NCP, w->off + 1, T_I8, &b) && pgv(NCP, w->off + 2, T_I8, &c)
                 && pgv(NCP, w->off + 3, T_I8, &d) && pgv(NCP, w->off + 4, T_I8, &e) && pgv(NCP, w->off - 8, T_I16, &s);
            v = (c != 0 ? 10 : 0) + (a != 0) + (e != 0 ? 100 + s * 100 : 0) + (d != 0 ? 1000 : 0) + (b != 0 ? 10000 : 0);
            break;
        case V_SUBLEVEL:   /* !c[0xbd6] -> -2; s[0xbcc] != 0 -> (s[0xbca] > 1 ? 4 : 2); else (s[0xbca] > 1 ? 3 : 1) */
            ok = pgv(NCP, 0xbd6, T_I8, &a) && pgv(NCP, 0xbcc, T_I16, &b) && pgv(NCP, 0xbca, T_I16, &c);
            v = a == 0 ? -2.0 : b != 0 ? (c > 1 ? 4.0 : 2.0) : (c > 1 ? 3.0 : 1.0);
            break;
        }
        if (!ok) continue;                  /* the page is missing in the part: NOT DECODED (Mastercam uses ControlDefaults) */
        if (w->flags & MPO_MAX749) { if (v >= 750.0) v = 749.0; }
        if (w->flags & MPO_MIN1) { if (v < 1e-12) v = 1.0; }                                       /* `<= 1e-12 && != 1e-12` */
        if (w->pg == MCH && w->off < 0) snprintf(src[i], sizeof src[i], "constant 0.0 (InitialAssignFromMD @1800b8a80)");
        else if (w->pg == MCH) snprintf(src[i], sizeof src[i], "machine record +%#x (InitialAssignFromMD @1800b8a80)", w->off);
        else snprintf(src[i], sizeof src[i], "control page %d ent +%#x (InitialAssignFromCD @1800b32b0)", w->pg, 0x80 + w->off);
        if (n < max) out[n] = (MpOverride){ w->var, v, src[i], w->flags, w->msg, w->bit, w->arg };
        n++;
    }
    return n;
}

/* InitialAssignFromMD's order: the rotary part (mp_md_rotary, for the first tool-table record's axis combination) then
   the feed limits, then InitialAssignFromCD (mp_cd_overrides) */
int mp_cd_overrides_ac(const McamFile *f, int axcombo, MpOverride *out, int max) {
    int n = mp_md_rotary(f, axcombo, out, max);
    if (n < 0) n = 0;                                     /* NOT DECODED rotary part: left out */
    int m = mp_cd_overrides(f, 0, n < max ? out + n : out, n < max ? max - n : 0);
    return m < 0 ? m : n + m;
}
